// Package tpmkey manages a non-exportable ECDSA P-256 signing key that lives
// inside a TPM 2.0 and uses it to mint ES256 JWTs. The private half of the key
// is generated by the TPM and never leaves it; callers only ever see the public
// key and signatures.
package tpmkey

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"

	"github.com/google/go-tpm/tpm2"
	"github.com/google/go-tpm/tpm2/transport"
)

// DefaultHandle is the persistent owner-hierarchy handle the signing key is
// stored at unless another is specified.
//
// The key is a child of the storage root key, so by TCG convention its handle
// belongs in the "Storage, Available" range, 0x81008000-0x8100FFFF (Registry
// of Reserved TPM 2.0 Handles and Localities, Table 11). go-tpm-tools picks
// its own handles from 0x81008F00-0x81008FFF, so stay below that. Other
// handles are taken by primary keys, reserved for future TCG use, or belong
// to the endorsement or platform hierarchies. The TPM doesn't enforce any of
// this, so a handle anywhere in 0x81000000-0x817FFFFF works today, but one in
// a reserved range may clash with whatever TCG later assigns there.
//
// Versions before 1.1.0 defaulted to 0x81010101, which is in the reserved
// part of the endorsement range. Keys created there keep working when given
// --tpm-key-handle=0x81010101 explicitly.
const DefaultHandle tpm2.TPMHandle = 0x81008101

// signingTemplate describes an ECDSA P-256 / SHA-256 signing key that is bound
// to this TPM (FixedTPM), cannot be duplicated to another parent
// (FixedParent), and whose private material was generated inside the TPM
// (SensitiveDataOrigin). Together these mean the private key cannot be
// exported in any form.
var signingTemplate = tpm2.TPMTPublic{
	Type:    tpm2.TPMAlgECC,
	NameAlg: tpm2.TPMAlgSHA256,
	ObjectAttributes: tpm2.TPMAObject{
		FixedTPM:            true,
		FixedParent:         true,
		SensitiveDataOrigin: true,
		UserWithAuth:        true,
		SignEncrypt:         true,
	},
	Parameters: tpm2.NewTPMUPublicParms(tpm2.TPMAlgECC, &tpm2.TPMSECCParms{
		Scheme: tpm2.TPMTECCScheme{
			Scheme: tpm2.TPMAlgECDSA,
			Details: tpm2.NewTPMUAsymScheme(tpm2.TPMAlgECDSA, &tpm2.TPMSSigSchemeECDSA{
				HashAlg: tpm2.TPMAlgSHA256,
			}),
		},
		CurveID: tpm2.TPMECCNistP256,
	}),
}

// Create generates a new signing key that is not bound to any boot state. See
// CreateWithPolicy.
func Create(tpm transport.TPM, handle tpm2.TPMHandle) (*ecdsa.PublicKey, error) {
	pub, _, err := CreateWithPolicy(tpm, handle, Policy{}, nil)
	return pub, err
}

// CreateWithPolicy generates a new signing key inside the TPM under a freshly
// derived storage root key and persists it at handle. It refuses to overwrite
// a key that already exists at handle.
//
// If p is bound, the key can only be used through a policy session that
// satisfies p (see Policy), and it's only persisted once it has signed through
// such a session. signed holds the signed PCR policies to choose from when
// p.PCRSigner is set. It returns the values p.PCRs were bound to.
func CreateWithPolicy(tpm transport.TPM, handle tpm2.TPMHandle, p Policy, signed []SignedPCRPolicy) (*ecdsa.PublicKey, [][]byte, error) {
	if _, err := (tpm2.ReadPublic{ObjectHandle: handle}).Execute(tpm); err == nil {
		return nil, nil, fmt.Errorf("a key already exists at handle 0x%x", uint32(handle))
	}

	template := signingTemplate
	var values [][]byte
	if p.Bound() {
		if len(p.PCRs) > 0 {
			var err error
			if values, err = ReadPCRs(tpm, p.PCRs); err != nil {
				return nil, nil, err
			}
			if err := checkNotReset(p.PCRs, values); err != nil {
				return nil, nil, err
			}
		}
		digest, err := authPolicy(p, values)
		if err != nil {
			return nil, nil, err
		}
		template.AuthPolicy = tpm2.TPM2BDigest{Buffer: digest}
		// Without this, the empty password would also satisfy the USER role
		// for TPM2_Sign, bypassing the policy entirely.
		template.ObjectAttributes.UserWithAuth = false
	}

	loaded, err := loadNewKey(tpm, template)
	if err != nil {
		return nil, nil, err
	}
	defer tpm2.FlushContext{FlushHandle: loaded.ObjectHandle}.Execute(tpm)

	// Sign through the same policy session the plugin will use, so that the
	// TPM itself checks everything, including the signature on the PCR policy.
	// Otherwise a bad one only shows up at the plugin's first signature, after
	// the JWKS has been uploaded.
	if p.Bound() {
		if err := probeSign(tpm, loaded.ObjectHandle, loaded.Name, p, signed); err != nil {
			return nil, nil, fmt.Errorf("refusing to create a key the current boot can't use: %w", err)
		}
	}

	if _, err := (tpm2.EvictControl{
		Auth:             tpm2.TPMRHOwner,
		ObjectHandle:     tpm2.NamedHandle{Handle: loaded.ObjectHandle, Name: loaded.Name},
		PersistentHandle: handle,
	}).Execute(tpm); err != nil {
		return nil, nil, fmt.Errorf("failed to persist signing key at handle 0x%x: %w", uint32(handle), err)
	}

	pub, _, err := Public(tpm, handle)
	return pub, values, err
}

// loadNewKey creates a key from template under a freshly derived storage root
// key and loads it. The storage root key is flushed on return: satisfying a
// signed policy loads the PCR-signing key as well, and a TPM may only have
// room for three transient objects.
func loadNewKey(tpm transport.TPM, template tpm2.TPMTPublic) (*tpm2.LoadResponse, error) {
	srk, err := tpm2.CreatePrimary{
		PrimaryHandle: tpm2.TPMRHOwner,
		InPublic:      tpm2.New2B(tpm2.ECCSRKTemplate),
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("failed to create storage root key: %w", err)
	}
	defer tpm2.FlushContext{FlushHandle: srk.ObjectHandle}.Execute(tpm)
	parent := tpm2.NamedHandle{Handle: srk.ObjectHandle, Name: srk.Name}

	created, err := tpm2.Create{
		ParentHandle: parent,
		InPublic:     tpm2.New2B(template),
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("failed to create signing key: %w", err)
	}

	loaded, err := tpm2.Load{
		ParentHandle: parent,
		InPrivate:    created.OutPrivate,
		InPublic:     created.OutPublic,
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("failed to load signing key: %w", err)
	}
	return loaded, nil
}

// KeyInfo describes the key at a persistent handle.
type KeyInfo struct {
	Public *ecdsa.PublicKey
	Name   tpm2.TPM2BName
	// AuthPolicy is empty for a key that is not bound to boot state.
	AuthPolicy []byte
	// UserWithAuth is true if the key can be used with its (empty) password.
	UserWithAuth bool
}

// Public reads the public half of the key at handle and verifies that it has
// the non-exportable signing attributes this package relies on.
func Public(tpm transport.TPM, handle tpm2.TPMHandle) (*ecdsa.PublicKey, tpm2.TPM2BName, error) {
	info, err := Inspect(tpm, handle)
	return info.Public, info.Name, err
}

// Inspect is Public, plus the key's authorization policy.
func Inspect(tpm transport.TPM, handle tpm2.TPMHandle) (KeyInfo, error) {
	rsp, err := tpm2.ReadPublic{ObjectHandle: handle}.Execute(tpm)
	if err != nil {
		return KeyInfo{}, fmt.Errorf("failed to read key at handle 0x%x: %w", uint32(handle), err)
	}
	public, err := rsp.OutPublic.Contents()
	if err != nil {
		return KeyInfo{}, fmt.Errorf("failed to decode public area: %w", err)
	}

	attrs := public.ObjectAttributes
	if public.Type != tpm2.TPMAlgECC || !attrs.FixedTPM || !attrs.FixedParent || !attrs.SensitiveDataOrigin || !attrs.SignEncrypt || attrs.Decrypt || attrs.Restricted {
		return KeyInfo{}, errors.New("key is not a non-exportable, unrestricted ECC signing key")
	}
	params, err := public.Parameters.ECCDetail()
	if err != nil {
		return KeyInfo{}, err
	}
	if params.CurveID != tpm2.TPMECCNistP256 {
		return KeyInfo{}, errors.New("key is not on the NIST P-256 curve")
	}

	pub, err := tpm2.Pub(*public)
	if err != nil {
		return KeyInfo{}, err
	}
	ecPub, ok := pub.(*ecdsa.PublicKey)
	if !ok {
		return KeyInfo{}, errors.New("key is not an ECDSA key")
	}
	return KeyInfo{
		Public:       ecPub,
		Name:         rsp.Name,
		AuthPolicy:   public.AuthPolicy.Buffer,
		UserWithAuth: attrs.UserWithAuth,
	}, nil
}

// sign asks the TPM to sign a SHA-256 digest and returns the signature in the
// fixed-width r||s form JWS ES256 requires. If p is bound, the key is used
// through a policy session satisfying p; signed holds the signed PCR policies
// to choose from when p.PCRSigner is set.
func sign(tpm transport.TPM, handle tpm2.TPMHandle, name tpm2.TPM2BName, digest []byte, p Policy, signed []SignedPCRPolicy) ([]byte, error) {
	if !p.Bound() {
		return signWith(tpm, tpm2.AuthHandle{Handle: handle, Name: name, Auth: tpm2.PasswordAuth(nil)}, digest)
	}

	var approved *SignedPCRPolicy
	if p.PCRSigner != nil {
		var err error
		if approved, err = matchSignedPolicy(tpm, p.PCRSigner, signed); err != nil {
			return nil, err
		}
	}

	for attempt := 1; ; attempt++ {
		sig, err := signWithPolicy(tpm, handle, name, digest, p, approved)
		switch {
		case errors.Is(err, tpm2.TPMRCPCRChanged) && attempt < pcrPolicyRetries:
			continue // Some PCR was extended mid-way; the session is spent, so start over.
		case errors.Is(err, tpm2.TPMRCPolicyFail):
			return nil, fmt.Errorf("TPM key policy not satisfied: %s: %w", mismatchReason(p), err)
		}
		return sig, err
	}
}

// probeSign signs a throwaway digest with the key, to find out whether the
// TPM lets the current boot use it.
func probeSign(tpm transport.TPM, handle tpm2.TPMHandle, name tpm2.TPM2BName, p Policy, signed []SignedPCRPolicy) error {
	digest := sha256.Sum256([]byte("tpmkey usability probe"))
	_, err := sign(tpm, handle, name, digest[:], p, signed)
	return err
}

func signWithPolicy(tpm transport.TPM, handle tpm2.TPMHandle, name tpm2.TPM2BName, digest []byte, p Policy, approved *SignedPCRPolicy) ([]byte, error) {
	// Neither the digest being signed nor the policy is secret, so the session
	// is deliberately unsalted and unbound.
	sess, closeSession, err := tpm2.PolicySession(tpm, tpm2.TPMAlgSHA256, 16)
	if err != nil {
		return nil, fmt.Errorf("failed to start policy session: %w", err)
	}
	defer closeSession()

	if err := satisfyPolicy(tpm, sess, p, approved); err != nil {
		return nil, err
	}
	return signWith(tpm, tpm2.AuthHandle{Handle: handle, Name: name, Auth: sess}, digest)
}

func signWith(tpm transport.TPM, key tpm2.AuthHandle, digest []byte) ([]byte, error) {
	rsp, err := tpm2.Sign{
		KeyHandle:  key,
		Digest:     tpm2.TPM2BDigest{Buffer: digest},
		InScheme:   tpm2.TPMTSigScheme{Scheme: tpm2.TPMAlgNull},
		Validation: tpm2.TPMTTKHashCheck{Tag: tpm2.TPMSTHashCheck, Hierarchy: tpm2.TPMRHNull},
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("TPM failed to sign: %w", err)
	}
	ecSig, err := rsp.Signature.Signature.ECDSA()
	if err != nil {
		return nil, err
	}
	return encodeES256(ecSig.SignatureR.Buffer, ecSig.SignatureS.Buffer)
}

// encodeES256 left-pads r and s to 32 bytes each. TPMs may return them with
// leading zero bytes stripped, but JWS requires the fixed-width form.
func encodeES256(r, s []byte) ([]byte, error) {
	if len(r) > 32 || len(s) > 32 {
		return nil, errors.New("TPM returned an oversized ECDSA signature")
	}
	out := make([]byte, 64)
	copy(out[32-len(r):32], r)
	copy(out[64-len(s):], s)
	return out, nil
}

// JWK is the public JSON Web Key for a P-256 key.
type JWK struct {
	Kty string `json:"kty"`
	Crv string `json:"crv"`
	X   string `json:"x"`
	Y   string `json:"y"`
	Alg string `json:"alg"`
	Use string `json:"use"`
	Kid string `json:"kid"`
}

// PublicJWK returns the JWK for pub. The kid is the RFC 7638 thumbprint of the
// key, so it is stable for a given key and unique per host.
func PublicJWK(pub *ecdsa.PublicKey) (JWK, error) {
	if pub.Curve != elliptic.P256() {
		return JWK{}, errors.New("key is not on the NIST P-256 curve")
	}
	raw, err := pub.Bytes() // 0x04 || X || Y
	if err != nil {
		return JWK{}, err
	}
	enc := base64.RawURLEncoding
	x, y := enc.EncodeToString(raw[1:33]), enc.EncodeToString(raw[33:65])
	// RFC 7638: required members only, lexicographic order, no whitespace.
	thumb := sha256.Sum256(fmt.Appendf(nil, `{"crv":"P-256","kty":"EC","x":"%s","y":"%s"}`, x, y))
	return JWK{
		Kty: "EC",
		Crv: "P-256",
		X:   x,
		Y:   y,
		Alg: "ES256",
		Use: "sig",
		Kid: enc.EncodeToString(thumb[:]),
	}, nil
}

// JWKS renders a JWK set containing the given keys, in the form accepted by
// `gcloud iam workload-identity-pools providers create-oidc --jwk-json-path`.
func JWKS(keys ...JWK) ([]byte, error) {
	return json.MarshalIndent(struct {
		Keys []JWK `json:"keys"`
	}{Keys: keys}, "", "  ")
}
